{
  "name": "opencode-agents-watcher",
  "version": "0.2.1",
  "type": "module",
  "description": "OpenCode TUI plugin - watch sub-agent status and recovery in the sidebar",
  "author": "RainingDaemons",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/RainingDaemons/opencode-agents-watcher.git"
  },
  "bugs": {
    "url": "https://github.com/RainingDaemons/opencode-agents-watcher/issues"
  },
  "homepage": "https://github.com/RainingDaemons/opencode-agents-watcher",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "subagent",
    "sidebar"
  ],
  "engines": {
    "opencode": ">=2.3.0"
  },
  "exports": {
    ".": "./dist/server.js",
    "./tui": "./dist/index.js"
  },
  "files": [
    "dist",
    "assets",
    "monitor.json.example"
  ],
  "dependencies": {
    "@opencode/client": "^2.3.0",
    "@opencode/plugin": "^2.3.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.4",
    "@opentui/solid": ">=0.8.4",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/theme": "^2.3.0",
    "@opentui/core": "^0.9.2",
    "@opentui/solid": "^0.9.2",
    "@types/bun": "^1.3.0",
    "solid-js": "^1.9.12",
    "typescript": "^5.9.0"
  },
  "scripts": {
    "build": "bun run script/build.mjs",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  }
}
